insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: describe vs explain$wdthseed$, $wdthseed$Data: enzyme rate 10 (20°C), 25 (37°C), 2 (60°C). (a) DESCRIBE (2): 'Rate rises from 10 to 25 between 20–37°C, then falls sharply to 2 at 60°C.' — pattern + numbers, zero reasons. (b) EXPLAIN the fall from 37–60°C (2): 'Above the optimum, heat breaks the weak bonds holding the active site's tertiary shape (denaturation), so substrate no longer fits and few complexes form.' — mechanism + consequence. Notice: (a) with reasons wastes time; (b) without because-links scores 1 of 2. Match the command, count your points, stop.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$State = facts. Describe = what. Explain = why (because-links). Compare = both + whereas. Evaluate = pros + cons + judgement. Suggest = reason from principles.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Commands are contracts: deliver exactly what each demands, in as many points as marks allow, with units and agents named. Technique turns B biology into A results.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod11:top02:les02$wdthseed$, $wdthseed$Data Questions and Timing$wdthseed$, $wdthseed$Tables, graphs and practical scenarios — a systematic attack plan plus paper strategy.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Data questions panic students who memorised notes but never practised thinking. A routine replaces panic — read, plan, answer, check.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The data routine$wdthseed$, $wdthseed$READ (1 min): read the STEM fully — underline the IV, DV and units; study EVERY table row and axis before touching questions. PLAN (30 s): note which module each sub-question raids; jot the 2–3 points each mark needs. ANSWER: calculations show FORMULA → SUBSTITUTION → ANSWER + UNITS (method marks survive arithmetic slips); % change = (change ÷ original) × 100; means exclude ANOMALIES (circle and note them — never silently delete); rates = quantity ÷ time. GRAPHS: axes (IV-X, DV-Y, units), 3/4-page scales, small precise plots, best-fit line/curve, title. CHECK (last 5 min of paper): units, contradictions, unanswered parts, candidate details. PAPER STRATEGY: first pass — all confident questions; second pass — hard ones with fresh eyes; never leave blanks; if stuck >3 min, mark and move.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the full routine$wdthseed$, $wdthseed$Table: light distance 10/20/30/40 cm → bubbles 42/24/11/6 per min. (a) Describe the trend (2): 'As distance increases from 10 to 40 cm, bubble rate falls steeply from 42 to 6 per minute — fastest drop between 10–20 cm.' (b) Explain using limiting factors (2): 'Greater distance lowers light intensity (limiting factor), slowing the light-dependent reactions, so less oxygen evolves per minute.' (c) Suggest why 10 cm might be anomalous-friendly (1): 'Lamp heat warms the tube — temperature confounds the light effect; a heat shield/water bath would control it.' Three sub-questions, three modules (M9 rate, M9 factors, M10 design) — the routine handles all.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$READ (IV/DV/units) → PLAN (modules, points) → ANSWER (formula-sub-answer-units) → CHECK.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod11:top02:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Data questions yield to routine: read precisely, plan by module, calculate with shown working, check at the end. Two passes and zero blanks maximise every paper.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod11:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 11 reading: revisit YOUR weakest chapters (use module-exam scores to choose). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod11$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod11:prac$wdthseed$, $wdthseed$Timed Drill — 20 Questions in 25 Minutes$wdthseed$, $wdthseed$Practise full exam pace: read, calculate, write and move on under time pressure.$wdthseed$, $wdthseed$Use any 20 quiz/exam questions you previously missed (or the module quizzes below) as your drill paper.$wdthseed$, $wdthseed$1. Collect 20 questions you got wrong before (or re-take Module 1–3 quizzes fresh). 2. Set a 25-minute timer, phone away, desk clear — exam conditions. 3. Answer in order; mark-and-move any question exceeding 90 seconds. 4. Mark harshly against the explanations (half-understood = wrong). 5. Log every miss in three columns: question | correct concept | WHY I missed it (knowledge/technique/panic). 6. Re-study the top 3 miss-reasons for 30 minutes, then re-attempt those questions untimed. SAFETY: none — but sleep properly; cramming past midnight destroys recall.$wdthseed$, $wdthseed$Timer, quiet space, notebook miss-log.$wdthseed$, $wdthseed$Score + miss-log table + 30-minute repair notes on top 3 reasons.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["Genuine timed conditions described honestly","Miss-log categorises every miss by reason","Repair notes show the corrected concepts in own words"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod11$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod11:asg$wdthseed$, $wdthseed$Weakness Clinic Report$wdthseed$, $wdthseed$Diagnose your three weakest areas from module-exam history, re-study them, and prove the gains.$wdthseed$, $wdthseed$1. List your scores on all module quizzes/exams taken so far (honest numbers). 2. Identify your THREE weakest topics (lowest scores or slowest answers). 3. For each: state the topic, quote one question you missed with YOUR wrong answer, explain the correct concept in your own words (100+ words each), and re-take that module's quiz — record old vs new score. 4. Build a 7-day revision timetable (topics × days × minutes) targeting the weaknesses first. 5. Submit scores table + three repairs + timetable (450–550 words plus tables).$wdthseed$, $wdthseed$Real scores from your attempts; invented gains are obvious and score zero.$wdthseed$, $wdthseed$Score history + 3 concept repairs with re-take evidence + 7-day timetable.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 150, $wdthseed$TEXT$wdthseed$, $wdthseed$["Honest score history with correctly identified weakest three","Each repair explains the concept accurately in own words with re-take evidence","Timetable is specific, weakness-first and realistic"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod11$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod11:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
