insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod12:top01:les01$wdthseed$, $wdthseed$Definitions and Equations Master List$wdthseed$, $wdthseed$The 20 definitions and 4 equations no candidate may fumble.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Examiners cannot mark what they cannot recognise. These definitions and equations are the currency of every biology paper — mint them now.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Twenty definitions$wdthseed$, $wdthseed$Cover the right column; recall; check. (1) Diffusion — net movement of particles from high to low concentration down a gradient. (2) Osmosis — net movement of water from high to low water concentration across a partially permeable membrane. (3) Active transport — movement against a gradient using ATP and carriers. (4) Enzyme — specific protein catalyst with an active site, unchanged by reaction. (5) Denaturation — irreversible loss of 3D shape (heat/extreme pH) destroying function. (6) Photosynthesis — CO2 + water → glucose + oxygen using light and chlorophyll. (7) Aerobic respiration — glucose + oxygen → CO2 + water + large energy. (8) Gene — DNA section coding one trait. (9) Allele — one version of a gene. (10) Genotype — allele pair carried; phenotype — trait expressed. (11) Mitosis — one division → 2 identical diploid cells (growth/repair). (12) Meiosis — two divisions → 4 unique haploid cells (gametes). (13) Natural selection — variation + competition + differential survival + inheritance shifting allele frequencies. (14) Species — interbreeding group producing fertile offspring. (15) Ecosystem — community plus non-living environment. (16) Trophic level — feeding step from producers. (17) Homeostasis — maintaining constant internal conditions by negative feedback. (18) Reflex — fast involuntary response via receptor→sensory→relay→motor→effector. (19) Transpiration — water loss from leaves driving xylem pull. (20) Germination — sprouting requiring water + oxygen + warmth.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Four equations, zero confusion$wdthseed$, $wdthseed$PHOTOSYNTHESIS: 6CO2 + 6H2O →(light/chlorophyll) C6H12O6 + 6O2. AEROBIC RESPIRATION: C6H12O6 + 6O2 → 6CO2 + 6H2O + energy (~30 ATP). ANAEROBIC (muscle): glucose → lactic acid + small energy. ANAEROBIC (yeast): glucose → ethanol + CO2 + small energy. Direction discipline: photosynthesis BUILDS glucose (needs input); respiration BREAKS it (releases output). Common swap: writing respiration's arrow for photosynthesis — check every equation's direction before moving on. Word equations earn full marks where symbols are not demanded; add symbols only when confident.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the 10-minute self-test$wdthseed$, $wdthseed$Method: fold paper in half. Left: numbers 1–20. Without notes, write each definition from the titles alone (diffusion, osmosis, ...). Time: 10 minutes. Marking: exact = tick; close = half; missing/wrong = cross. Score under 16: re-learn crosses using Module 11's chain technique, sleep, re-test tomorrow (spaced repetition beats cramming). Score 16+: attempt the 4 equations blind, then diagrams (next lesson). Repeat daily until 20/20 twice running — mastery is consecutive perfection, not one lucky pass.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$20 definitions + 4 equations = the paper's currency.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Definitions decide marks: precise terms, named structures, stated conditions. Drill them spaced and blind until perfect is routine.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod12:top01:les02$wdthseed$, $wdthseed$Diagrams You Must Draw$wdthseed$, $wdthseed$The six most-examined diagrams and how to reproduce each for full marks.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=6mgkoqcm6Sg$wdthseed$, $wdthseed$A perfect diagram can earn 6 marks in 3 minutes — the best rate in the paper. These six appear year after year.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The six diagrams$wdthseed$, $wdthseed$(1) PLANT CELL: wall, membrane, cytoplasm, nucleus, vacuole, chloroplast, mitochondrion — rectangular with even walls. (2) ANIMAL CELL: membrane, cytoplasm, nucleus, mitochondrion — rounded, NO wall/vacuole/chloroplasts. (3) HEART (double circulation): four chambers, aorta/vena cava/pulmonary vessels, valves, arrows showing flow + O2 colours. (4) LEAF SECTION: cuticle, upper epidermis, palisade, spongy + air spaces, lower epidermis with stomata/guard cells, vein (xylem above, phloem below). (5) FLOWER (half-section): sepals, petals, anther/filament, stigma/style/ovary/ovule. (6) REFLEX ARC: receptor → sensory → spinal cord relay → motor → muscle, with CNS box and direction arrows. RULES (Module 10): large, sharp pencil, single lines, no shading, ruled touching labels, title + magnification. Annotate ONE function per label where space allows ('xylem — carries water up').$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the heart in 3 minutes$wdthseed$, $wdthseed$Drill: draw the heart from memory, timed. Minute 1 — outline: two atria (top, thin walls), two ventricles (bottom, left wall THICK), septum dividing. Minute 2 — vessels: aorta arching from left ventricle, vena cava entering right atrium, pulmonary artery leaving right ventricle, pulmonary veins entering left atrium. Minute 3 — valves (dots + labels: bicuspid, tricuspid, semilunars) + flow arrows + title 'Vertical section of the mammalian heart'. Self-mark: 1 per correct chamber, vessel pair, valve set, arrows, title. Under 5: redraw immediately — motor memory builds through repetition, not reading.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
