insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod12:top02:les01$wdthseed$, $wdthseed$Sitting the Mock$wdthseed$, $wdthseed$Exam-day simulation: conditions, conduct and the module mock examination.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$This is the dress rehearsal: 10 questions, 40 minutes, no notes, no pauses. Treat it as the final and the final will feel familiar.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Mock protocol$wdthseed$, $wdthseed$CONDITIONS: quiet room, clear desk, timer set to 40 minutes, phone OFF and away, water only. CONDUCT: attempt the module assessment below in ONE sitting, in order, showing working for calculations; mark-and-move past 3-minute stalls; use remaining time to review flagged questions only. FORBIDDEN: notes, videos, re-reading lessons mid-mock, extra time ('just 5 more minutes' invalidates the rehearsal). SCORING: 60%+ = proceed to the final exam (Topic 2, Lesson 2); 50–59% = repair misses (assignment) then re-sit once; below 50% = return to weakest modules (Module 11 clinic) before re-sitting. HONESTY WARNING: inflating a mock score only relocates failure to the final — the mock is a measuring instrument, and cheating breaks the instrument.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: post-mock triage$wdthseed$, $wdthseed$A student scores 7/10, missing Q3 (nitrogen bacteria), Q6 (heart trace), Q9 (leaf starch logic). TRIAGE: Q3 = knowledge gap → re-study Module 7 Lesson 2.1 (bacteria names) + flashcards. Q6 = retrieval gap → redraw the heart 3x timed (Lesson 2 drill). Q9 = reasoning gap → re-read Module 9's destarch logic + write the conclusion pattern 5x. REPAIR TIME: 45 minutes total, weakest first. RE-TEST: re-attempt all three blind tomorrow. RULE: every miss gets a named repair within 24 hours — misses without repairs repeat in the final.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les01:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Mock = 40 min, one sitting, no notes, no extra time.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les01:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Simulate reality, score honestly, triage misses within a day. The mock's job is diagnosis — let it diagnose.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod12:top02:les02$wdthseed$, $wdthseed$Entering the Final Examination$wdthseed$, $wdthseed$What the final demands, how completion and certification work, and staying calm.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Twelve modules behind you; one examination ahead. Know the rules, trust the preparation, and walk in calm.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Final rules and certification$wdthseed$, $wdthseed$THE FINAL EXAMINATION: 30 questions, 90 minutes, 3 attempts (best counts), 60% pass mark — covering all 12 modules (see the course final exam for the full instructions). COMPLETION requires ALL of: 80%+ lessons finished, 60%+ quiz average, every assignment submitted AND passed, and the final exam passed at 60%+. Certificates are issued AUTOMATICALLY when the system verifies completion — each carries a unique certificate number verifiable on the platform; there is no manual step and no fee beyond the course itself. RESULTS: attempts are graded instantly with explanations for review; after passing, download your certificate from the Certificates page and verify its number. If an attempt fails, the miss-triage from Lesson 1 applies: repair within 24 hours, then use the next attempt — three attempts reward steady improvers.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Calm-day tactics$wdthseed$, $wdthseed$NIGHT BEFORE: light review of checklists only (no new material), pack requirements, sleep 7+ hours — sleep consolidates memory; all-night cramming deletes it. EXAM TIME: arrive early, breathe slowly (4 counts in, 6 out) to settle nerves, read ALL instructions first, execute Module 11's two-pass strategy, and trust first instincts on MCQs unless new reasoning emerges (changed answers are wrong more often than right). AFTER: do not post-mortem with friends (it only seeds doubt); review the official explanations when released; celebrate effort whatever the outcome — then repair and re-attempt if needed. You have revised systematically for 12 modules. The final is familiar ground.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the 60% maths$wdthseed$, $wdthseed$Question: 'I scored 55% on attempt 1. What must change for attempt 2?' Step 1 — Count: 30 questions × 55% ≈ 16–17 correct; passing needs 18+. Step 2 — Triage the ~13 misses by module (e.g. 4 genetics, 3 ecology, 2 practicals, 4 scattered). Step 3 — Repair the CLUSTERS first: 4 genetics misses → 45-minute Module 5 repair (ratios + sex-linkage) converts up to 4 marks; ecology 3 → 30-minute cycles review. Step 4 — Re-attempt after 24 hours: fixing two clusters typically adds 5–7 marks → 70%+. Moral: clustered misses are concentrated gold — mine them first.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Final: 30 Qs, 90 min, 3 attempts, 60% pass. Completion: 80% lessons + 60% quiz avg + assignments passed + final passed.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod12:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Know the thresholds, earn them systematically, and let the system certify real achievement. Calm, sleep and triage carry you the last mile. Good luck — you are ready.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod12:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 12 reading: final targeted review — use the OpenStax end-of-chapter questions for your weakest chapters. Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod12$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod12:prac$wdthseed$, $wdthseed$Exam-Day Simulation$wdthseed$, $wdthseed$Rehearse the complete final-exam experience: setup, sitting, review and recovery.$wdthseed$, $wdthseed$Tomorrow is the final. Today you run the full simulation and fix the last gaps.$wdthseed$, $wdthseed$1. PREPARE the room exactly as Lesson 1 specifies (desk, timer 40 min, water, phone off). 2. SIT the module mock examination below in one go — no pauses, no notes. 3. MARK immediately and harshly; log every miss (question | concept | reason). 4. REPAIR each miss with a 10-minute targeted re-study (open the named module lesson, write the concept in own words). 5. RE-ATTEMPT all missed questions blind and confirm 100% on the re-attempt. 6. Write a 5-line readiness statement: score, misses, repairs done, re-attempt score, one-line confidence note. SAFETY: take a 10-minute walk between marking and repair — fresh eyes learn faster.$wdthseed$, $wdthseed$Timer, quiet room, notebook.$wdthseed$, $wdthseed$Mock score + miss log + repair notes + 100% re-attempt + readiness statement.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 120, $wdthseed$TEXT$wdthseed$, $wdthseed$["Real simulated conditions with honest timing","Every miss logged with concept and reason","Repairs completed with confirmed 100% re-attempt"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod12$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod12:asg$wdthseed$, $wdthseed$Readiness Declaration$wdthseed$, $wdthseed$Declare final-exam readiness with evidence: scores, repairs and a calm-day plan.$wdthseed$, $wdthseed$Submit: (1) Your mock score with the miss log (question | concept | reason). (2) For EACH miss: the corrected concept in your own words (50+ words each) plus re-attempt result. (3) Your completion checklist status: lessons % done, quiz average, assignments submitted/passed (copy from your dashboard). (4) Your calm-day plan: sleep time, arrival, materials, first-5-minutes routine (100 words). (5) One paragraph on what you will do if attempt 1 fails (triage plan, not panic). 400–500 words plus tables.$wdthseed$, $wdthseed$Evidence must match real dashboard data; declarations without evidence score zero.$wdthseed$, $wdthseed$Miss repairs + completion status + calm-day plan + contingency paragraph.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Every mock miss repaired accurately in own words","Completion status honestly reported against all four gates","Calm-day and contingency plans specific and realistic"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod12$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod12:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
